static std::vector<uint8_t> notification(size_t segments = 1, uint8_t marker = 42) {
  std::vector<uint8_t> data(41 + segments * 36);
  for (size_t i = 0; i < data.size(); ++i) data[i] = uint8_t(i * 13 + marker);
  data[0] = 0; data[1] = 1; data[3] = marker; data[11] = 12;
  data[39] = segments; data[40] = 36;
  return data;
}
static bool queue(const std::vector<uint8_t>& data) {
  const int sendCount = sdk.sendCount;
  const auto calls = sdk.calls;
  const bool accepted = castleTekESPNowQueue(data.data(), data.size());
  CHECK(!criticalDepth);
  CHECK(sdk.sendCount == sendCount);
  CHECK(sdk.calls == calls); // HTTP/state mutation only copies; no SDK work or wait.
  return accepted;
}
static void handle() { castleTekESPNowHandle(); CHECK(!criticalDepth); }
