static void testImmediateError() {
  start();
  const auto failed = notification(32, 9), replacement = notification(1, 17);
  CHECK(queue(failed));
  sdk.sendError = ESP_ERR_ESPNOW_INTERNAL;
  handle();
  CHECK(sdk.sendCount == 1);
  CHECK(queue(replacement));
  sdk.sendError = ESP_OK;
  for (int i = 0; i < 200; ++i) handle();
  CHECK(sdk.sendCount == 1); // No hot retry, even when the controller loop is busy.
  clockNow += 99; handle(); CHECK(sdk.sendCount == 1);
  ++clockNow; pumpComplete(1);
  CHECK(statusESPNow == ESP_NOW_STATE_ON);
  verifyNotification(1, replacement);
  CHECK(sdk.frames.size() == 2); // Failed whole notification was abandoned.

  // A failure completion is also terminal for that partial notification.
  CHECK(queue(failed)); handle(); complete(ESP_NOW_SEND_FAIL);
  CHECK(queue(replacement)); handle();
  CHECK(sdk.frames.size() == 4);
  complete(); handle(); verifyNotification(3, replacement);
}
