static void testTimeout() {
  start();
  CHECK(queue(notification(32, 9))); handle();
  CHECK(queue(notification(1, 17)));
  clockNow += 999; handle();
  CHECK(statusESPNow == ESP_NOW_STATE_ON && sdk.sendCount == 1);
  ++clockNow; handle();
  CHECK(statusESPNow == ESP_NOW_STATE_ERROR && sdk.sendCount == 1);
  for (int i = 0; i < 50; ++i) { clockNow += 1000; handle(); }
  CHECK(sdk.sendCount == 1); // No waiting loop, restart churn, or newer SDK send.
  CHECK(sdk.initCount == 1 && sdk.deinitCount == 0);
  const uint8_t incoming[] = {1,2,3};
  receive(senderMAC, incoming, sizeof(incoming)); handle();
  CHECK(delivered.size() == 1 && delivered[0].bytes == std::vector<uint8_t>({1,2,3}));
  CHECK(sdk.sendCount == 1 && statusESPNow == ESP_NOW_STATE_ERROR);
  // Missing completions are peer-scoped; another peer cannot release quarantine.
  const auto callbacks = sdk.calls;
  sdk.sent(senderMAC, ESP_NOW_SEND_SUCCESS); sdk.sent(nullptr, ESP_NOW_SEND_SUCCESS);
  handle(); CHECK(sdk.sendCount == 1 && sdk.calls == callbacks);
}
