    const auto sends = sdk.sendCount;
    const auto receives = delivered.size();
    if (cycle % 2) WiFi.connected = false; else enableESPNow = false;
    handle();
    CHECK(!sdk.initialized && sdk.peers.empty() && !sdk.sent && !sdk.received);
    CHECK(statusESPNow == ESP_NOW_STATE_UNINIT);
    CHECK(!queue(notification()));
