  verifyNotification(size_t(sends + 1), notification(1, 92));
  castleTekESPNowStop();
  clockNow = 0xFFFF'FE0Bu;
  sdk.initError = ESP_FAIL; handle();
  const auto starts = sdk.initCount;
  clockNow += 999; handle(); CHECK(sdk.initCount == starts);
  sdk.initError = ESP_OK; ++clockNow; start();
  clockNow = 0xFFFF'FE0Bu;
